"use client";

import { AbsoluteFill, Series } from "remotion";
import { BrandScene } from "./scenes/brand";
import { CommandScene } from "./scenes/command";
import { FeaturesScene } from "./scenes/features";
import { HookScene } from "./scenes/hook";
import { LearningLoopScene } from "./scenes/learning-loop";
import { MontageScene } from "./scenes/montage";
import { OutroScene } from "./scenes/outro";
import { ProductUiScene } from "./scenes/product-ui";
import { SpeedScene } from "./scenes/speed";
import { TopicsScene } from "./scenes/topics";
import {
  type IntroducingProductProps,
  normalizeIntroducingProductProps,
} from "./types";

export type { IntroducingProductStudioProps } from "./schema";
export {
  DEFAULT_INTRODUCING_PRODUCT_PROPS,
  introducingProductSchema,
} from "./schema";
export type { IntroducingProductProps, ProductFeature } from "./types";
export {
  getIntroducingProductDuration,
  getIntroducingProductSceneStart,
  INTRODUCING_PRODUCT_DURATION,
  INTRODUCING_PRODUCT_TIMELINE,
} from "./types";

export function IntroducingProduct(props: IntroducingProductProps = {}) {
  const content = normalizeIntroducingProductProps(props);
  const timeline = content.timeline;

  return (
    <AbsoluteFill
      className={content.className || undefined}
      style={{
        backgroundColor: content.theme.darkBackground,
        overflow: "hidden",
        scale: content.theme.canvasScale,
      }}
    >
      <Series>
        <Series.Sequence name="Hook" durationInFrames={timeline.hook}>
          <HookScene {...content} sceneDuration={timeline.hook} />
        </Series.Sequence>
        <Series.Sequence name="Command" durationInFrames={timeline.command}>
          <CommandScene {...content} sceneDuration={timeline.command} />
        </Series.Sequence>
        <Series.Sequence name="Brand reveal" durationInFrames={timeline.brand}>
          <BrandScene {...content} sceneDuration={timeline.brand} />
        </Series.Sequence>
        <Series.Sequence
          name="Product UI"
          durationInFrames={timeline.productUi}
        >
          <ProductUiScene {...content} sceneDuration={timeline.productUi} />
        </Series.Sequence>
        <Series.Sequence
          name="Value counter"
          durationInFrames={timeline.speedScene}
        >
          <SpeedScene {...content} sceneDuration={timeline.speedScene} />
        </Series.Sequence>
        <Series.Sequence
          name="Feature walkthrough"
          durationInFrames={timeline.features}
        >
          <FeaturesScene {...content} sceneDuration={timeline.features} />
        </Series.Sequence>
        <Series.Sequence
          name="Card montage"
          durationInFrames={timeline.montage}
        >
          <MontageScene {...content} sceneDuration={timeline.montage} />
        </Series.Sequence>
        <Series.Sequence
          name="Learning loop"
          durationInFrames={timeline.learningLoop}
        >
          <LearningLoopScene
            {...content}
            sceneDuration={timeline.learningLoop}
          />
        </Series.Sequence>
        <Series.Sequence
          name="Topic cascade"
          durationInFrames={timeline.topics}
        >
          <TopicsScene {...content} sceneDuration={timeline.topics} />
        </Series.Sequence>
        <Series.Sequence name="Outro" durationInFrames={timeline.outro}>
          <OutroScene {...content} sceneDuration={timeline.outro} />
        </Series.Sequence>
      </Series>
    </AbsoluteFill>
  );
}

import {
  DEFAULT_INTRODUCING_PRODUCT_PROPS,
  type IntroducingProductStudioProps,
  introducingProductSchema,
} from "./schema";

export type ProductFeature =
  IntroducingProductStudioProps["content"]["featureCards"][number];
export type EasingPreset =
  IntroducingProductStudioProps["scenes"]["hook"]["easing"];
export type IntroducingProductTimeline = Omit<
  IntroducingProductStudioProps["timeline"],
  "speed"
>;

export type DeepPartial<T> = T extends readonly unknown[]
  ? T
  : T extends object
    ? { [K in keyof T]?: DeepPartial<T[K]> }
    : T;

interface LegacyIntroducingProductProps {
  productName?: string;
  tagline?: string;
  hookLine?: string;
  contrastLine?: string;
  command?: string;
  benefit?: string;
  metric?: string;
  featureCards?: ProductFeature[];
  topics?: string[];
  accentColor?: string;
  warmColor?: string;
  logoUrl?: string;
  screenshotUrls?: string[];
  speed?: number;
  className?: string;
}

export type IntroducingProductProps =
  DeepPartial<IntroducingProductStudioProps> & LegacyIntroducingProductProps;

export type NormalizedIntroducingProductProps = IntroducingProductStudioProps;

export interface IntroducingProductSceneProps
  extends IntroducingProductStudioProps {
  sceneDuration: number;
}

export const INTRODUCING_PRODUCT_TIMELINE: IntroducingProductTimeline = {
  hook: DEFAULT_INTRODUCING_PRODUCT_PROPS.timeline.hook,
  command: DEFAULT_INTRODUCING_PRODUCT_PROPS.timeline.command,
  brand: DEFAULT_INTRODUCING_PRODUCT_PROPS.timeline.brand,
  productUi: DEFAULT_INTRODUCING_PRODUCT_PROPS.timeline.productUi,
  speedScene: DEFAULT_INTRODUCING_PRODUCT_PROPS.timeline.speedScene,
  features: DEFAULT_INTRODUCING_PRODUCT_PROPS.timeline.features,
  montage: DEFAULT_INTRODUCING_PRODUCT_PROPS.timeline.montage,
  learningLoop: DEFAULT_INTRODUCING_PRODUCT_PROPS.timeline.learningLoop,
  topics: DEFAULT_INTRODUCING_PRODUCT_PROPS.timeline.topics,
  outro: DEFAULT_INTRODUCING_PRODUCT_PROPS.timeline.outro,
};

export type IntroducingProductScene = keyof IntroducingProductTimeline;

const INTRODUCING_PRODUCT_SCENES: IntroducingProductScene[] = [
  "hook",
  "command",
  "brand",
  "productUi",
  "speedScene",
  "features",
  "montage",
  "learningLoop",
  "topics",
  "outro",
];

export function getIntroducingProductDuration(
  timeline:
    | IntroducingProductTimeline
    | IntroducingProductStudioProps["timeline"] = INTRODUCING_PRODUCT_TIMELINE,
): number {
  return INTRODUCING_PRODUCT_SCENES.reduce(
    (sum, scene) => sum + Math.max(1, Math.round(timeline[scene])),
    0,
  );
}

export const INTRODUCING_PRODUCT_DURATION = getIntroducingProductDuration();

export function getIntroducingProductSceneStart(
  scene: IntroducingProductScene,
  timeline: IntroducingProductTimeline = INTRODUCING_PRODUCT_TIMELINE,
): number {
  let start = 0;
  for (const name of INTRODUCING_PRODUCT_SCENES) {
    if (name === scene) return start;
    start += timeline[name];
  }
  return start;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function mergeDeep<T>(base: T, override: DeepPartial<T> | undefined): T {
  if (!isRecord(base) || !isRecord(override)) {
    return (override === undefined ? base : override) as T;
  }

  const result: Record<string, unknown> = { ...base };
  for (const [key, value] of Object.entries(override)) {
    if (value === undefined) continue;
    const current = result[key];
    result[key] =
      isRecord(current) && isRecord(value) ? mergeDeep(current, value) : value;
  }
  return result as T;
}

export function normalizeIntroducingProductProps(
  props: IntroducingProductProps = {},
): NormalizedIntroducingProductProps {
  const merged = mergeDeep(DEFAULT_INTRODUCING_PRODUCT_PROPS, props);
  const legacyContent = {
    productName: props.productName,
    tagline: props.tagline,
    hookLine: props.hookLine,
    contrastLine: props.contrastLine,
    command: props.command,
    benefit: props.benefit,
    metric: props.metric,
    featureCards: props.featureCards,
    topics: props.topics,
    logoUrl: props.logoUrl,
    screenshotUrls: props.screenshotUrls,
  };

  for (const [key, value] of Object.entries(legacyContent)) {
    if (value !== undefined) {
      (merged.content as Record<string, unknown>)[key] = value;
    }
  }
  if (props.accentColor !== undefined) {
    merged.theme.accentColor = props.accentColor;
  }
  if (props.warmColor !== undefined) {
    merged.theme.warmColor = props.warmColor;
  }
  if (props.speed !== undefined) merged.timeline.speed = props.speed;
  if (props.className !== undefined) merged.className = props.className;

  return introducingProductSchema.parse(merged);
}

import { Easing } from "remotion";
import type { EasingPreset } from "./types";

export function resolveIntroducingProductEasing(
  preset: EasingPreset,
): (value: number) => number {
  switch (preset) {
    case "linear":
      return Easing.linear;
    case "ease-in":
      return Easing.in(Easing.cubic);
    case "ease-out":
      return Easing.out(Easing.cubic);
    case "ease-in-out":
      return Easing.inOut(Easing.cubic);
    case "snappy":
      return Easing.bezier(0.2, 0.9, 0.2, 1.12);
    case "spring":
      return Easing.spring({ damping: 16, stiffness: 180 });
    case "smooth":
      return Easing.bezier(0.16, 1, 0.3, 1);
  }
}

export function sceneFrame(
  frame: number,
  speed: number,
  sceneDuration: number,
): number {
  return Math.min(sceneDuration, frame * speed);
}

export function at(sceneDuration: number, progress: number): number {
  return sceneDuration * progress;
}

import type { ReactNode } from "react";
import {
  AbsoluteFill,
  Easing,
  Img,
  interpolate,
  useCurrentFrame,
} from "remotion";
import type { IntroducingProductStudioProps } from "./schema";
import type { ProductFeature } from "./types";

type Theme = IntroducingProductStudioProps["theme"];

export function DarkStage({
  theme,
  children,
}: {
  theme: Theme;
  children: ReactNode;
}) {
  const frame = useCurrentFrame();
  return (
    <AbsoluteFill
      style={{
        backgroundColor: theme.darkBackground,
        color: theme.darkText,
        fontFamily: theme.fontFamily,
        overflow: "hidden",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: theme.gridOpacity,
          backgroundImage:
            "linear-gradient(rgba(255,255,255,.09) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.09) 1px, transparent 1px)",
          backgroundSize: `${theme.gridSize}px ${theme.gridSize}px`,
          translate: `${-(frame % theme.gridSize)}px ${-(frame % theme.gridSize)}px`,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: "12%",
          right: "12%",
          bottom: -180,
          height: 330,
          borderRadius: "50%",
          background: `linear-gradient(90deg, ${theme.accentColor}, ${theme.warmColor})`,
          filter: `blur(${theme.glowBlur}px)`,
          opacity: theme.glowOpacity,
          scale: interpolate(frame % 120, [0, 60, 120], [0.96, 1.04, 0.96]),
        }}
      />
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(circle at 50% 42%, transparent 0%, rgba(0,0,0,.12) 48%, rgba(0,0,0,.82) 100%)",
        }}
      />
      {children}
    </AbsoluteFill>
  );
}

export function LightStage({
  theme,
  children,
}: {
  theme: Theme;
  children: ReactNode;
}) {
  return (
    <AbsoluteFill
      style={{
        backgroundColor: theme.lightBackground,
        color: theme.lightText,
        fontFamily: theme.fontFamily,
        overflow: "hidden",
      }}
    >
      <div
        style={{
          position: "absolute",
          left: "7%",
          right: "7%",
          bottom: -175,
          height: 310,
          borderRadius: "50%",
          background: `linear-gradient(90deg, ${theme.accentColor}, ${theme.warmColor})`,
          filter: `blur(${theme.glowBlur + 2}px)`,
          opacity: theme.glowOpacity * 0.67,
        }}
      />
      {children}
    </AbsoluteFill>
  );
}

export function BrandMark({
  productName,
  logoUrl,
  accentColor,
  size = 68,
  showName = true,
}: Pick<IntroducingProductStudioProps["content"], "productName" | "logoUrl"> & {
  accentColor: string;
  size?: number;
  showName?: boolean;
}) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: size * 0.24 }}>
      {logoUrl ? (
        <Img
          name="Product logo"
          src={logoUrl}
          style={{ width: size, height: size, objectFit: "contain" }}
        />
      ) : (
        <div
          style={{
            width: size,
            height: size,
            borderRadius: "42% 58% 52% 48% / 58% 42% 58% 42%",
            background: `radial-gradient(circle at 35% 28%, #fff 0 8%, transparent 9%), radial-gradient(circle at 64% 38%, #b8a7ff 0 7%, transparent 8%), linear-gradient(145deg, #d8d0ff, ${accentColor} 58%, #19121f)`,
            boxShadow: `0 0 ${size * 0.7}px ${accentColor}88`,
          }}
        />
      )}
      {showName ? (
        <div
          style={{
            fontSize: size * 0.56,
            fontWeight: 700,
            letterSpacing: "-0.045em",
          }}
        >
          {productName}
        </div>
      ) : null}
    </div>
  );
}

function Sparkline({ color }: { color: string }) {
  return (
    <svg viewBox="0 0 260 80" style={{ width: "100%", height: 80 }}>
      <path
        d="M0 63 C28 56 34 68 58 48 S92 24 118 38 S151 64 175 36 S218 14 260 20"
        fill="none"
        stroke={color}
        strokeWidth="4"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function ProductWindow({
  productName,
  feature,
  accentColor,
  screenshotUrl,
  theme,
  compact = false,
}: {
  productName: string;
  feature: ProductFeature;
  accentColor: string;
  screenshotUrl?: string;
  theme: Theme;
  compact?: boolean;
}) {
  return (
    <div
      style={{
        width: compact ? theme.compactWindowWidth : theme.windowWidth,
        height: compact ? theme.compactWindowHeight : theme.windowHeight,
        overflow: "hidden",
        border: `1px solid ${theme.windowBorderColor}`,
        borderRadius: compact
          ? Math.max(0, theme.windowRadius - 8)
          : theme.windowRadius,
        background: theme.windowBackground,
        boxShadow: `0 0 0 1px ${accentColor}22, 0 30px 100px rgba(0,0,0,.65), 0 0 70px ${accentColor}42`,
      }}
    >
      {screenshotUrl ? (
        <Img
          name="Product screenshot"
          src={screenshotUrl}
          style={{ width: "100%", height: "100%", objectFit: "cover" }}
        />
      ) : (
        <div style={{ padding: compact ? 24 : 38 }}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              color: "#f8f7fb",
            }}
          >
            <div style={{ fontSize: compact ? 17 : 22, fontWeight: 700 }}>
              {productName}
            </div>
            <div style={{ display: "flex", gap: 8 }}>
              {[0, 1, 2].map((dot) => (
                <div
                  key={dot}
                  style={{
                    width: 7,
                    height: 7,
                    borderRadius: "50%",
                    background: dot === 0 ? accentColor : "#44434a",
                  }}
                />
              ))}
            </div>
          </div>
          <div style={{ marginTop: compact ? 32 : 58 }}>
            <div style={{ color: "#8e8c98", fontSize: compact ? 13 : 16 }}>
              {feature.eyebrow}
            </div>
            <div
              style={{
                marginTop: 10,
                maxWidth: 650,
                color: "#f8f7fb",
                fontSize: compact ? 28 : 43,
                fontWeight: 620,
                letterSpacing: "-0.035em",
                lineHeight: 1.06,
              }}
            >
              {feature.title}
            </div>
            <div
              style={{
                marginTop: 14,
                maxWidth: 610,
                color: "#8e8c98",
                fontSize: compact ? 14 : 19,
                lineHeight: 1.45,
              }}
            >
              {feature.description}
            </div>
          </div>
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1.5fr 1fr",
              gap: 20,
              marginTop: compact ? 26 : 48,
            }}
          >
            <div
              style={{
                padding: compact ? 14 : 20,
                border: "1px solid rgba(255,255,255,.1)",
                borderRadius: 16,
                background: "rgba(255,255,255,.025)",
              }}
            >
              <Sparkline color={accentColor} />
            </div>
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
                padding: compact ? 14 : 20,
                border: "1px solid rgba(255,255,255,.1)",
                borderRadius: 16,
                background: "rgba(255,255,255,.025)",
              }}
            >
              <div style={{ color: "#8e8c98", fontSize: compact ? 12 : 14 }}>
                Momentum
              </div>
              <div
                style={{
                  color: "#f8f7fb",
                  fontSize: compact ? 23 : 34,
                  fontWeight: 680,
                  marginTop: 5,
                }}
              >
                {feature.stat ?? "Live"}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export function FadeEdges() {
  return (
    <AbsoluteFill
      style={{
        pointerEvents: "none",
        boxShadow: "inset 0 0 130px rgba(0,0,0,.78)",
        color: "#ffffff",
      }}
    />
  );
}

export const smooth = Easing.bezier(0.16, 1, 0.3, 1);

import { Interactive, interpolate, useCurrentFrame } from "remotion";
import { at, resolveIntroducingProductEasing, sceneFrame } from "../easing";
import { DarkStage } from "../shared";
import type { IntroducingProductSceneProps } from "../types";

export function HookScene(props: IntroducingProductSceneProps) {
  const config = props.scenes.hook;
  const frame = sceneFrame(
    useCurrentFrame(),
    props.timeline.speed,
    props.sceneDuration,
  );
  const split = at(props.sceneDuration, config.secondBeatAt);
  const secondBeat = frame >= split;
  const localFrame = secondBeat ? frame - split : frame;
  const localDuration = secondBeat ? props.sceneDuration - split : split;
  const copy = secondBeat ? props.content.contrastLine : props.content.hookLine;
  const easing = resolveIntroducingProductEasing(config.easing);

  return (
    <DarkStage theme={props.theme}>
      <Interactive.Div
        name="Hook statement"
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "80px 96px",
          color: props.theme.darkText,
          fontSize: interpolate(
            localFrame,
            [0, at(localDuration, 0.55), localDuration],
            [config.startFontSize, config.enterFontSize, config.settleFontSize],
            {
              easing,
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            },
          ),
          fontWeight: config.fontWeight,
          letterSpacing: `${config.letterSpacing}em`,
          lineHeight: 0.94,
          textAlign: "center",
          whiteSpace: "nowrap",
          opacity: interpolate(
            localFrame,
            [
              0,
              at(localDuration, config.fadeInEnd),
              at(localDuration, config.fadeOutStart),
              localDuration,
            ],
            [0, 1, 1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
          ),
          filter: `blur(${interpolate(
            localFrame,
            [
              0,
              at(localDuration, config.fadeInEnd * 2),
              at(localDuration, config.fadeOutStart),
              localDuration,
            ],
            [config.blur, 0, 0, config.blur],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
          )}px)`,
          translate: `${
            config.x +
            interpolate(
              localFrame,
              [0, at(localDuration, 0.55)],
              [config.enterOffsetX, 0],
              { easing, extrapolateLeft: "clamp", extrapolateRight: "clamp" },
            )
          }px ${config.y}px`,
        }}
      >
        {copy}
      </Interactive.Div>
    </DarkStage>
  );
}

import { Interactive, interpolate, useCurrentFrame } from "remotion";
import { at, resolveIntroducingProductEasing, sceneFrame } from "../easing";
import { DarkStage } from "../shared";
import type { IntroducingProductSceneProps } from "../types";

export function CommandScene(props: IntroducingProductSceneProps) {
  const config = props.scenes.command;
  const frame = sceneFrame(
    useCurrentFrame(),
    props.timeline.speed,
    props.sceneDuration,
  );
  const easing = resolveIntroducingProductEasing(config.easing);
  const visible = Math.floor(
    interpolate(
      frame,
      [
        at(props.sceneDuration, config.typeStart),
        at(props.sceneDuration, config.typeEnd),
      ],
      [0, props.content.command.length],
      { easing, extrapolateLeft: "clamp", extrapolateRight: "clamp" },
    ),
  );

  return (
    <DarkStage theme={props.theme}>
      <Interactive.Div
        name="Command field"
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          display: "flex",
          alignItems: "center",
          width: interpolate(
            frame,
            [0, at(props.sceneDuration, config.expandEnd)],
            [config.collapsedWidth, config.expandedWidth],
            { easing, extrapolateLeft: "clamp", extrapolateRight: "clamp" },
          ),
          height: config.height,
          padding: `0 ${config.paddingX}px`,
          border: `1px solid ${props.theme.windowBorderColor}`,
          borderRadius: 999,
          backgroundColor: props.theme.darkBackground,
          boxShadow: `-18px 0 55px ${props.theme.accentColor}aa, 20px 0 60px ${props.theme.warmColor}80`,
          color: props.theme.darkText,
          fontSize: config.fontSize,
          fontWeight: config.fontWeight,
          letterSpacing: "-0.035em",
          overflow: "hidden",
          opacity: interpolate(
            frame,
            [
              0,
              at(props.sceneDuration, config.fadeInEnd),
              at(props.sceneDuration, config.fadeOutStart),
              props.sceneDuration,
            ],
            [0, 1, 1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
          ),
          translate: `calc(-50% + ${config.x}px) calc(-50% + ${config.y}px)`,
        }}
      >
        <span style={{ whiteSpace: "nowrap" }}>
          {props.content.command.slice(0, visible)}
        </span>
        <span
          style={{
            width: 3,
            height: config.fontSize * 1.2,
            marginLeft: 5,
            background: props.theme.accentColor,
            opacity: Math.floor(frame / 10) % 2 === 0 ? 1 : 0,
          }}
        />
      </Interactive.Div>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: config.cursorWidth,
          height: config.cursorHeight,
          opacity: interpolate(
            frame,
            [
              at(props.sceneDuration, 0.58),
              at(props.sceneDuration, 0.72),
              at(props.sceneDuration, config.fadeOutStart),
              props.sceneDuration,
            ],
            [0, 1, 1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
          ),
          translate: `${config.cursorX}px ${config.cursorY}px`,
          rotate: "-22deg",
          background: props.theme.accentColor,
          clipPath: "polygon(0 0, 100% 70%, 58% 76%, 45% 100%)",
          filter: `drop-shadow(0 0 14px ${props.theme.accentColor})`,
        }}
      />
    </DarkStage>
  );
}

import { interpolate, useCurrentFrame } from "remotion";
import { at, resolveIntroducingProductEasing, sceneFrame } from "../easing";
import { BrandMark, DarkStage } from "../shared";
import type { IntroducingProductSceneProps } from "../types";

export function BrandScene(props: IntroducingProductSceneProps) {
  const config = props.scenes.brand;
  const frame = sceneFrame(
    useCurrentFrame(),
    props.timeline.speed,
    props.sceneDuration,
  );
  const easing = resolveIntroducingProductEasing(config.easing);
  return (
    <DarkStage theme={props.theme}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: interpolate(
            frame,
            [
              0,
              at(props.sceneDuration, config.fadeInEnd),
              at(props.sceneDuration, config.fadeOutStart),
              props.sceneDuration,
            ],
            [0, 1, 1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
          ),
          scale: interpolate(
            frame,
            [0, at(props.sceneDuration, config.settleAt)],
            [config.startScale, config.endScale],
            { easing, extrapolateLeft: "clamp", extrapolateRight: "clamp" },
          ),
